use crate::ArtifactRef;
use semio_framework_value::{RetirementDemand, RetainedCloneGrant, retained_clone::RetainedCloneSource};
use semio_framework_value_persistent::retained_equality::RetainedEqualityOwner;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes.max(257),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source(value:ArtifactRef,bank:&mut Bank)->RetainedCloneSource<ArtifactRef>{let d=RetainedCloneSource::<ArtifactRef>::owned_constructor_demand::<()>();let g=grant(RetirementDemand{copy_bytes:RetainedCloneSource::<ArtifactRef>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()});let mut admission=RetainedCloneSource::admission_owned(value,());let mut output=None;for _ in 0..64{if admission.terminal_is_empty(){break}if admission.phase()=="ready"{let turn=admission.take_output(&mut output,g);let work=turn.work;let p=turn.result.unwrap().progress();bank.debit(work,p);}else{let turn=admission.advance(g);let work=turn.work;let p=turn.result.unwrap().progress();bank.debit(work,p);}}output.expect("staged artifact reference source")}
fn parse(value:&serde_json::Value)->ArtifactRef{use semio_framework_value::FromValue;ArtifactRef::from_value(serde_json::from_value(value.clone()).unwrap()).unwrap()}
fn pointers(value:&ArtifactRef)->[*const u8;4]{[value.artifact_id.as_ptr(),value.dialect.artifact_kind.as_ptr(),value.dialect.standard.as_ptr(),value.dialect.subset.as_ptr()]}
fn source_close(source:&mut RetainedCloneSource<ArtifactRef>,bank:&mut Bank){while !source.terminal_is_empty(){let g=grant(source.next_close_demand(4096).unwrap());let turn=source.close_step(g);let work=turn.work;let p=turn.result.unwrap().progress();bank.debit(work,p);assert!(p.fits(g));}}
fn close(owner:&mut RetainedEqualityOwner<ArtifactRef>,mut born:usize,mut released:usize,bank:&mut Bank){owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demand(4096).unwrap();let g=grant(d);assert_eq!(bank.step(owner.close_step(RetainedCloneGrant{maximum_items:0,..g})).progress(),Default::default());if d.release_bytes>0{assert_eq!(bank.step(owner.close_step(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g})).progress(),Default::default());}let p=bank.step(owner.close_step(g)).progress();assert!(p.fits(g));born+=p.retained_capacity_bytes;released+=p.released_bytes;}assert_eq!(born,released);}
#[test]
fn original_artifact_reference_equality_preserves_all_exact_identity_fields(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let mut bank=Bank::new();let mut left=source(parse(&row["left"]),&mut bank);let mut right=source(parse(&row["right"]),&mut bank);let original=pointers(left.borrow().get());let mut owner=RetainedEqualityOwner::<ArtifactRef>::new();let(mut born,mut released,mut turns)=(0,0,0);while owner.result().is_none(){let d=owner.demand(left.borrow(),right.borrow(),257).unwrap();let g=grant(d);if d.copy_bytes>0{assert_eq!(bank.equal(owner.advance(left.borrow(),right.borrow(),257,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})).progress,Default::default());}if d.capacity_bytes>0{assert_eq!(bank.equal(owner.advance(left.borrow(),right.borrow(),257,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g})).progress,Default::default());}let p=bank.equal(owner.advance(left.borrow(),right.borrow(),257,g)).progress;assert!(p.fits(g));born+=p.retained_capacity_bytes;released+=p.released_bytes;turns+=1;assert!(turns<10000);}assert_eq!(owner.result(),row["equal"].as_bool());assert_eq!(left.borrow().get()==right.borrow().get(),row["equal"].as_bool().unwrap());close(&mut owner,born,released,&mut bank);assert_eq!(pointers(left.borrow().get()),original);drop(owner);source_close(&mut left,&mut bank);source_close(&mut right,&mut bank);}}
#[test]
fn original_artifact_reference_equality_cancellation_keeps_source_and_cursor_custody(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){for cut in fixture["cancelCuts"].as_array().unwrap(){let mut bank=Bank::new();let mut left=source(parse(&row["left"]),&mut bank);let mut right=source(parse(&row["right"]),&mut bank);let mut foreign=source(parse(&row["left"]),&mut bank);let original=pointers(right.borrow().get());let mut owner=RetainedEqualityOwner::<ArtifactRef>::new();let(mut born,mut released,mut turns)=(0,0,0);while owner.result().is_none()&&turns<cut.as_u64().unwrap()as usize{let g=grant(owner.demand(left.borrow(),right.borrow(),257).unwrap());let p=bank.equal(owner.advance(left.borrow(),right.borrow(),257,g)).progress;assert!(p.fits(g));born+=p.retained_capacity_bytes;released+=p.released_bytes;turns+=1;}if turns>0{assert!(owner.verify(foreign.borrow(),right.borrow()).is_err());}close(&mut owner,born,released,&mut bank);assert_eq!(pointers(right.borrow().get()),original);drop(owner);source_close(&mut left,&mut bank);source_close(&mut right,&mut bank);source_close(&mut foreign,&mut bank);}}}

struct Bank{remaining:RetainedCloneGrant}
impl Bank{
 fn new()->Self{let law:serde_json::Value=serde_json::from_str(include_str!("work.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("work.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}let s=&law["stock"];Self{remaining:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:s["release"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize}}}
 fn debit(&mut self,work:u64,p:semio_framework_value::RetainedCloneProgress){assert!(work<=self.remaining.maximum_items as u64);assert!(p.fits(self.remaining));self.remaining.maximum_items-=work as usize;self.remaining.maximum_copy_bytes-=p.copied_bytes;self.remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;self.remaining.maximum_release_bytes-=p.released_bytes;}
 fn step(&mut self,turn:semio_framework_value::RetainedWorkOutcome)->semio_framework_value::RetainedCloneStep{let work=turn.work;let step=turn.result.unwrap();self.debit(work,step.progress());step}
 fn equal(&mut self,turn:semio_framework_value::RetainedWorkOutcome<semio_framework_value_persistent::RetainedEqualityStep>)->semio_framework_value_persistent::RetainedEqualityStep{let work=turn.work;let step=turn.result.unwrap();self.debit(work,step.progress);step}
}
